prop:pure-qfi.source:
\begin{proposition}[Pure-state quantum Fisher information]\label{prop:pure-qfi}
Let $P=hh^*$ with $\norm h=1$. The pairing $\mathcal H_P$ is independent
of the chosen directional SLDs. For $A,B\in T_P$ and
$v\in\C^D$ with $h^*v=0$, it satisfies
\begin{equation}\label{eq:intrinsic-qfi}
 \mathcal H_P[A,B]=2\tr(AB),\qquad \mathcal H_P[hv^*+vh^*,hv^*+vh^*]=4\norm v^2.
\end{equation}
In a chart (Definition~\ref{def:pure-chart}) with tangent basis $A_j=\partial_j\Gamma(\theta)$,
$[H(\theta)]_{jk}=\mathcal H_P[A_j,A_k]$ and
$\mathcal H_P[A,B]=u^{\mathsf T}H(\theta)w$ whenever
$A=\sum_{j=1}^p u_jA_j$ and $B=\sum_{k=1}^p w_kA_k$, with
$u,w\in\R^p$.
\end{proposition}

thm:p1clt.source:
\begin{theorem}[Asymptotic normality with inverse-information covariance]
\label{thm:p1clt}
Under the hypotheses of Theorem~\ref{thm:p1}, the ridge estimator and
the physical output are asymptotically normal:
\begin{equation}\label{eq:p1clt}
 n^{1/2}(\widehat\theta_n-\theta_0)\Longrightarrow
 \mathcal N_3(0,\Sigma_L),\qquad \Sigma_L=(\mathcal I_L^\star)^{-1},
\end{equation}
and the asymptotic normality in~\eqref{eq:p1clt} also holds with $c_n$
in place of $\widehat\theta_n$.
Explicitly,
\begin{equation}\label{eq:mixedcovariance}
 \begin{split}
 \Sigma_B&=3(\Id_3-\theta_0\theta_0^{\mathsf T}),\\
 \Sigma_F&=(2+s_0)\left(\Id_3-
              \frac{\theta_0\theta_0^{\mathsf T}}{1+s_0}\right).
 \end{split}
\end{equation}
The assertions cover the maximally mixed state, single-shot updates,
and all completed-batch subsequences.
\end{theorem}

prop:phasepair.source:
\begin{proposition}[Phase pairing]\label{prop:phasepair}
The effects~\eqref{eq:phaseunitary} form an informationally complete
measurement on the full state space and have positive reference probabilities.
In the reference coordinates~\eqref{eq:referencechart}, centered at $P_{\rm ref}$,
\begin{equation}\label{eq:phasepairfisher}
 \mathcal I_{\mathsf E}(0)=H(0)/2=\Id_{2d}/2
\end{equation}
Equivalently, $\mathcal J_{\mathsf E,P_{\rm ref}}=\tfrac12\mathcal H_{P_{\rm ref}}$ as bilinear
forms on $T_{P_{\rm ref}}$; this is Fisher symmetry at $P_{\rm ref}$.
\end{proposition}

thm:p2.source:
\begin{theorem}[Strong consistency and Fisher information convergence]
\label{thm:p2}
Fix $D\ge2$, a reference POVM satisfying (C1)--(C2) with rank-one effects,
$\lambda,\eta>0$, a pure truth $P_0$, and batches~\eqref{eq:batches}.
The paired adaptive experiment and estimators in
Algorithm~\ref{alg:phase-paired}, defined by~\eqref{eq:pureridge}
and~\eqref{eq:pure-tangent-objective}, satisfy, almost surely,
\begin{equation}\label{eq:p2limit}
 \begin{aligned}
 \widehat A_n&\to P_0,\quad\widehat P_n\to P_0,
       \quad\widehat P_n^{\rm eff}\to P_0,
       &&(n=N_j,\ j\to\infty),\\
 U_tP_{\rm ref}U_t^*&\to P_0,\qquad \mathcal J_{a_t,P_0}\to \mathcal H_{P_0}/2,
       &&(t\to\infty),\\
 \frac1n\sum_{t\le n}\mathcal J_{a_t,P_0}&\to \mathcal H_{P_0}/2,
       &&(n=N_j,\ j\to\infty).
 \end{aligned}
\end{equation}
Here $t\to\infty$ runs through all measured copies. The limits indexed
by $n$ hold along the completed-batch sample sizes $n=N_j$, $j\to\infty$,
where $N_j$ is the cumulative number of copies after batch $j$
defined in~\eqref{eq:batches}.
\end{theorem}

cor:mixed-mean-loss.source:
\begin{corollary}[Mixed-qubit expected-loss attainment]\label{cor:mixed-mean-loss}
Under the hypotheses of Theorem~\ref{thm:p1clt}, let $c_n$ be the
safeguarded output~\eqref{eq:bures-safeguard} for
Algorithm~\ref{alg:mixed-bures} or the projected
output~\eqref{eq:qubitcontroller} for Algorithm~\ref{alg:mixed-frobenius}.
Along $n=N_j$, $j\to\infty$,
\begin{equation}\label{eq:mixed-oracle-mean-loss}
 \begin{aligned}
 n\,\E_{\theta_0}D_B^2\{\rho(c_n),\rho(\theta_0)\}
   &\longrightarrow 9/4 &&\text{(Algorithm~\ref{alg:mixed-bures})},\\
 n\,\E_{\theta_0}\norm{\rho(c_n)-\rho(\theta_0)}_F^2
   &\longrightarrow (2+s_0)^2/2 &&\text{(Algorithm~\ref{alg:mixed-frobenius})}.
 \end{aligned}
\end{equation}
\end{corollary}

cor:oracle-mean-loss.source:
\begin{corollary}[Pure-state expected-loss attainment]\label{cor:oracle-mean-loss}
Under the hypotheses of Theorem~\ref{thm:p2efficient}, the reported
tangent-corrected projector of Algorithm~\ref{alg:phase-paired}
satisfies, along $n=N_j$, $j\to\infty$,
\begin{equation}\label{eq:oracle-mean-loss}
 \begin{split}
 n\,\E_{P_0}D_B(\widehat P_n^{\rm eff},P_0)^2&\longrightarrow d,\\
 n\,\E_{P_0}\norm{\widehat P_n^{\rm eff}-P_0}_F^2&\longrightarrow2d.
 \end{split}
\end{equation}
\end{corollary}
